package ui

import (
	"fmt"
	"html/template"
	"strings"
)

// Icon renders a Lucide icon inline as SVG: {{icon "search"}}. Extra classes,
// such as a size, follow the name: {{icon "search" "size-5"}}. Icons are
// decorative, so label the control around them. An unknown name is an error,
// which fails the render instead of drawing nothing.
func Icon(name string, class ...string) (template.HTML, error) {
	body, ok := icons[name]
	if !ok {
		return "", fmt.Errorf("ui: no icon %q", name)
	}
	c := template.HTMLEscapeString(strings.Join(append([]string{"icon"}, class...), " "))
	// body is vendored markup from the map below; the class is escaped.
	return template.HTML(`<svg class="` + c + `" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">` + body + `</svg>`), nil //nolint:gosec
}

